                local_cnt[best]++;
                double *ls_best = &local_sum[best * D];
                ls_best[0] += p[0];
                ls_best[1] += p[1];
                ls_best[2] += p[2];
                ls_best[3] += p[3];
                ls_best[4] += p[4];
                ls_best[5] += p[5];
                ls_best[6] += p[6];
                ls_best[7] += p[7];
            }

            /* Merge local thread buffers into global buffers */
            #pragma omp critical
